-- sparion-nacos.config_info DML
INSERT INTO `sparion-nacos`.`config_info` (`id`,`data_id`,`group_id`,`content`,`md5`,`gmt_create`,`gmt_modified`,`src_user`,`src_ip`,`app_name`,`tenant_id`,`c_desc`,`c_use`,`effect`,`type`,`c_schema`,`encrypted_data_key`) VALUES (1,'sparion-common.properties','DEFAULT_GROUP','# jwt\njwt.subject=sparion\njwt.secret-key=wpFudcbry3tdCY8h2?Fk$A,+yxd.ZHR/7-aFZRpGrKWYTN!h:|JvS4.KNU;,EC,=kZPZKu&hjUZ<G$n;R<ESfAKCa7&GW,;TjG?%VuDy/ZvKtRr<f5&uj_*?3D*<PKV_Rkf&$:+$FRK3k?/y.Z,cc7!!6*ZH|%xPy<-p_/-c6$|3CjQRQvuMp/ABEn,*7phuNCWc$;!4>hv%Fpka<G/,nrpn5Rp:KS3DQK52.p|Y.hTuHkTMcJr88r5&&CmevVQ4\njwt.expiration-time=10080000\njwt.refresh-secret-key=p.un%8*?yCd6vpVyB3<K;BJcGe2!Z$Sj*EJxH6Zd./SfajTdQQTCJr:BpHj3?v;FSPr+Hss*N5>S/5.uHkdrz,z=Je8x<Nf>JDW_YCy,z@4uW&QK%xyy:fdc3vM<b?M53QAQZ*P5RQ_Av&Vmj:Vb<dwn:2=zkPJnWd=+Zttb%|xQ=mRpCy45,5CjUKuCZWFQn6a,KCV8&<X7Rc5k;yK>?%s5?HUC_kTe.Hju$cvmD|&A%K8|&RAha6WwYtnDyteQ\njwt.refresh-expiration-time=10080000\n\n# 网关认证头\nsecurity.allow-header=x-forward-gateway\nsecurity.allow-header-value=sparion-gateway\n\n# 微服务名称\nsparion.application.sparion-gateway=sparion-gateway\nsparion.application.sparion-auth=sparion-auth\n\nsparion.application.sparion-module-system=sparion-module-system\nsparion.application.sparion-module-resource=sparion-module-resource\nsparion.application.sparion-module-ai=sparion-module-ai\nsparion.application.sparion-module-product=sparion-module-product\n\nsparion.application.sparion-external-client=sparion-external-client\nsparion.application.sparion-external-server=sparion-external-server\n\n# 开启虚拟线程支持\nspring.threads.virtual.enabled=true','44e48b1f3435a3103588950cbcc61930','2025-03-12 10:48:46','2026-03-31 12:34:07','nacos','172.19.0.1','','','','','','properties','',''),(2,'sparion-gateway.properties','DEFAULT_GROUP','spring.cloud.gateway.routes[0].id=sparion-auth\nspring.cloud.gateway.routes[0].uri=lb://${sparion.application.sparion-auth}\nspring.cloud.gateway.routes[0].predicates[0]=Path=/api/auth/**\nspring.cloud.gateway.routes[0].filters[0]